// ---------------------------------------------------------------------------------------------
// The mock

/** The collections the mock serves; a test replaces one to plant its own rows. */
export interface FdsCollections {
  jurisdictions: JsonObject[];
  classifications: JsonObject[];
  categories: JsonObject[];
  campaigns: JsonObject[];
  publicBodies: JsonObject[];
  laws: JsonObject[];
  requests: JsonObject[];
  documents: JsonObject[];
  tags: JsonObject[];
}

const DEFAULTS: FdsCollections = {
  jurisdictions: JURISDICTIONS,
  classifications: CLASSIFICATIONS,
  categories: CATEGORIES,
  campaigns: CAMPAIGNS,
  publicBodies: PUBLIC_BODIES,
  laws: LAWS,
  requests: REQUESTS.map((r) => (r["id"] === 373204 ? REQUEST_373204 : r)),
  documents: DOCUMENTS,
  tags: TAGS,
};

/** A copy of `row` with `changes`: a planted variant of a recorded row. */
export function variant(row: JsonObject, changes: JsonObject): JsonObject {
  return { ...row, ...changes };
}

const fold = (value: unknown): string =>
  String(value ?? "")
    .normalize("NFC")
    .toLocaleLowerCase("de");

/** The numeric id at the end of a resource URI, or the `id` of an embedded object. */
function idOf(value: unknown): number | undefined {
  if (typeof value === "string") {
    const match = /\/(\d+)\/?$/.exec(value);
    return match === null ? undefined : Number(match[1]);
  }
  if (value !== null && typeof value === "object" && "id" in value) return Number((value as { id: unknown }).id);
  return undefined;
}

/** A list page of `rows` (the API's offset and limit, default and most 50), with the honest total. */
function page(url: URL, rows: readonly JsonObject[]): HttpResponse {
  const offset = Number(url.searchParams.get("offset") ?? 0);
  const limit = Math.min(Number(url.searchParams.get("limit") ?? 50), 50);
  const next = offset + limit < rows.length ? `${url.origin}${url.pathname}?limit=${limit}&offset=${offset + limit}` : null;
  return jsonResponse({ meta: { limit, next, offset, previous: null, total_count: rows.length }, objects: rows.slice(offset, offset + limit) });
}

const notFound = (): HttpResponse => jsonResponse({ detail: "Nicht gefunden." }, 404);

/** The answer of the mock API to one request. */
export function fdsAnswer(request: HttpRequest, overrides: Partial<FdsCollections> = {}): HttpResponse {
  const data = { ...DEFAULTS, ...overrides };
  const url = new URL(request.url);
  const q = url.searchParams;
  const path = url.pathname;
  const words = (row: JsonObject, ...keys: string[]): boolean => {
    const want = q.get("q");
    return want === null || keys.some((key) => fold(row[key]).includes(fold(want)));
  };
  const is = (key: string, actual: unknown): boolean => q.get(key) === null || String(actual) === q.get(key);
  const detail = (rows: readonly JsonObject[], prefix: string): HttpResponse | undefined => {
    const match = new RegExp(`^${prefix}(\\d+)/$`).exec(path);
    if (match === null) return undefined;
    const row = rows.find((r) => r["id"] === Number(match[1]));
    return row === undefined ? notFound() : jsonResponse(row);
  };
  const autocomplete = (rows: readonly JsonObject[], valueKey: string): HttpResponse =>
    page(url, rows.filter((r) => fold(r["name"]).includes(fold(q.get("q")))).map((r) => ({ value: r[valueKey] ?? null, label: r["name"] ?? null })));
  const classificationName = (row: JsonObject): string | undefined => {
    const id = idOf(row["classification"]);
    return data.classifications.find((c) => c["id"] === id)?.["name"] as string | undefined;
  };

  switch (path) {
    case "/api/v1/jurisdiction/":
      return page(url, data.jurisdictions);
    case "/api/v1/campaign/":
      return page(url, data.campaigns);
    case "/api/v1/classification/":
      return page(url, data.classifications.filter((c) => words(c, "name")));
    case "/api/v1/category/":
      return page(url, data.categories.filter((c) => words(c, "name")));
    case "/api/v1/publicbody/autocomplete/":
      return autocomplete(data.publicBodies, "id");
    case "/api/v1/law/autocomplete/":
      return autocomplete(data.laws, "id");
    case "/api/v1/request/tags/autocomplete/":
      return page(url, data.tags.filter((t) => fold(t["value"]).includes(fold(q.get("q")))));
    case "/api/v1/publicbody/":
    case "/api/v1/publicbody/search/": {
      const category = q.get("category") ?? q.get("categories");
      return page(
        url,
        data.publicBodies.filter(
          (b) =>
            words(b, "name", "other_names") &&
            is("jurisdiction", idOf(b["jurisdiction"])) &&
            is("classification", idOf(b["classification"])) &&
            (category === null || (Array.isArray(b["categories"]) && b["categories"].some((c) => String(idOf(c)) === category))),
        ),
      );
    }
    case "/api/v1/law/":
      return page(
        url,
        data.laws.filter((l) => words(l, "name") && is("jurisdiction", idOf(l["jurisdiction"])) && is("meta", l["meta"]) && is("id", l["id"])),
      );
    case "/api/v1/request/":
      return page(
        url,
        data.requests.filter(
          (r) =>
            is("status", r["status"]) &&
            is("resolution", r["resolution"]) &&
            is("jurisdiction", idOf(r["jurisdiction"])) &&
            is("law", idOf(r["law"])) &&
            is("public_body", idOf(r["public_body"])) &&
            is("campaign", idOf(r["campaign"])) &&
            is("classification", classificationName(r["public_body"] as JsonObject)) &&
            // The recorded rows don't carry their body's categories: a category filter matches none.
            q.get("categories") === null &&
            (q.get("tags") === null || (Array.isArray(r["tags"]) && r["tags"].includes(q.get("tags") as string))),
        ),
      );
    case "/api/v1/request/search/": {
      const slug = q.get("jurisdiction");
      const jurisdiction = slug === null ? undefined : data.jurisdictions.find((j) => j["slug"] === slug)?.["id"];
      return page(url, data.requests.filter((r) => words(r, "title", "description") && (slug === null || idOf(r["jurisdiction"]) === jurisdiction)));
    }
    case "/api/v1/document/":
      return page(
        url,
        data.documents.filter(
          (d) =>
            is("publicbody", idOf(d["publicbody"])) &&
            is("foirequest", idOf(d["foirequest"])) &&
            (q.get("tag") === null || (Array.isArray(d["tags"]) && d["tags"].includes(q.get("tag") as string))),
        ),
      );
  }
  return (
    detail(data.publicBodies, "/api/v1/publicbody/") ??
    detail(data.laws, "/api/v1/law/") ??
    detail(data.requests, "/api/v1/request/") ??
    detail(data.documents, "/api/v1/document/") ??
    detail(data.classifications, "/api/v1/classification/") ??
    detail(data.categories, "/api/v1/category/") ??
    notFound()
  );
}

/** A mock transport on the recorded answers; `overrides` replaces whole collections. */
export function fdsApi(overrides: Partial<FdsCollections> = {}): MockTransport {
  return makeMockTransport((request) => fdsAnswer(request, overrides));
}
